SELECT CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'Insulin' AND h.intime BETWEEN 0 AND 24 THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.drug_type = 'Oral agent' AND h.intime BETWEEN 0 AND 24 THEN p.subject_id END), 0) AS ratio_insulin_first_24h, CAST(COUNT(DISTINCT CASE WHEN p.drug_type = 'Insulin' AND h.intime BETWEEN 24 AND 48 THEN p.subject_id END) AS FLOAT) / NULLIF(COUNT(DISTINCT CASE WHEN p.drug_type = 'Oral agent' AND h.intime BETWEEN 24 AND 48 THEN p.subject_id END), 0) AS ratio_insulin_final_24h, (ratio_insulin_first_24h - ratio_insulin_final_24h) AS absolute_difference FROM patients p JOIN pharmacy ph ON p.subject_id = ph.subject_id JOIN icustays h ON p.subject_id = h.subject_id WHERE p.gender = 'M' AND p.anchor_age = 73 AND h.intime BETWEEN 0 AND 48 AND (SELECT COUNT(DIAGNOSIS_ICD_CODE) FROM diagnoses_icd WHERE SUBJECT_ID = p.subject_id AND ICD_CODE IN ('44345005', '44345006')) > 0;